commands.command:
python3 -c "from pathlib import Path

h = Path(\"src/climate/runtime/Stage28RfDiagnostics.h\")
s = h.read_text()
old = \"explicit Stage28RfDiagnostics(Stage28RfDiagnosticsConfig config) noexcept;\"
new = \"Stage28RfDiagnostics(Stage28RfDiagnosticsConfig config, rf433::Rf433RmtLoopback& radio) noexcept;\"
assert old in s and new not in s
s = s.replace(old, new, 1)
assert \"bool begin() noexcept;\" in s
s = s.replace(\"bool begin() noexcept;\", \"bool begin(bool radio_ready) noexcept;\", 1)
assert \"  rf433::Rf433RmtLoopback loopback_;\" in s
s = s.replace(\"  rf433::Rf433RmtLoopback loopback_;\", \"  rf433::Rf433RmtLoopback& radio_;\", 1)
h.write_text(s)

cpp = Path(\"src/climate/runtime/Stage28RfDiagnostics.cpp\")
s = cpp.read_text()
old_ctor = \"\"\"Stage28RfDiagnostics::Stage28RfDiagnostics(Stage28RfDiagnosticsConfig config) noexcept
    : config_(config), loopback_(rf433::Rf433RmtLoopback::Config{config.tx_gpio, config.rx_gpio}) {}\"\"\"
new_ctor = \"\"\"Stage28RfDiagnostics::Stage28RfDiagnostics(Stage28RfDiagnosticsConfig config,
                                             rf433::Rf433RmtLoopback& radio) noexcept
    : config_(config), radio_(radio) {}\"\"\"
assert old_ctor in s
s = s.replace(old_ctor, new_ctor, 1)
old_begin = \"\"\"bool Stage28RfDiagnostics::begin() noexcept {
  ready_ = config_.enabled && loopback_.begin();\"\"\"
new_begin = \"\"\"bool Stage28RfDiagnostics::begin(bool radio_ready) noexcept {
  ready_ = config_.enabled && radio_ready;\"\"\"
assert old_begin in s
s = s.replace(old_begin, new_begin, 1)
assert s.count(\"loopback_.\") >= 1
s = s.replace(\"loopback_.\", \"radio_.\")
cpp.write_text(s)

rt = Path(\"src/climate/ClimateV6RealInputRuntime.cpp\")
s = rt.read_text()
old_ctor = \"\"\"  RuntimeIoOwner() noexcept
      : storage_config_(makeStorageConfig()), storage_logger_(storage_config_),
        rf_diagnostics_(rfDiagnosticsConfig()) {}
\"\"\"
new_ctor = \"\"\"  RuntimeIoOwner() noexcept
      : storage_config_(makeStorageConfig()), storage_logger_(storage_config_),
        rf_diagnostics_config_(rfDiagnosticsConfig()),
        rf_radio_({rf_diagnostics_config_.tx_gpio, rf_diagnostics_config_.rx_gpio}),
        rf_diagnostics_(rf_diagnostics_config_, rf_radio_) {}
\"\"\"
assert old_ctor in s
s = s.replace(old_ctor, new_ctor, 1)
old_access = \"\"\"  runtime::Stage28RfDiagnostics& rfDiagnostics() noexcept {
    return rf_diagnostics_;
  }

private:
  storage::Stage27TelemetryLogger::Config storage_config_{};
  storage::Stage27TelemetryLogger storage_logger_;
  runtime::Stage28RfDiagnostics rf_diagnostics_;
\"\"\"
new_access = \"\"\"  bool beginRf() noexcept {
    const bool radio_ready = rf_diagnostics_config_.enabled && rf_radio_.begin();
    return rf_diagnostics_.begin(radio_ready);
  }

  rf433::Rf433RmtLoopback& rfRadio() noexcept {
    return rf_radio_;
  }

  runtime::Stage28RfDiagnostics& rfDiagnostics() noexcept {
    return rf_diagnostics_;
  }

private:
  storage::Stage27TelemetryLogger::Config storage_config_{};
  storage::Stage27TelemetryLogger storage_logger_;
  runtime::Stage28RfDiagnosticsConfig rf_diagnostics_config_{};
  rf433::Rf433RmtLoopback rf_radio_;
  runtime::Stage28RfDiagnostics rf_diagnostics_;
\"\"\"
assert old_access in s
s = s.replace(old_access, new_access, 1)
assert \"  const bool rf_ready = rf_diagnostics.begin();\" in s
s = s.replace(\"  const bool rf_ready = rf_diagnostics.begin();\",
              \"  const bool rf_ready = runtime_io_owner.beginRf();\", 1)
rt.write_text(s)
"; git diff --check; git diff -- src/climate/runtime/Stage28RfDiagnostics.h src/climate/runtime/Stage28RfDiagnostics.cpp src/climate/ClimateV6RealInputRuntime.cpp

